// ============================================================
// AI MEETING / APPLICANT DATA NORMALIZATION
// Mode: Run Once for Each Item
// ============================================================

// Get the CURRENT item
const item = $input.item.json;


// ============================================================
// HELPER: Find a field regardless of capitalization/spacing
// ============================================================

function findField(data, possibleNames) {
  const keys = Object.keys(data);

  for (const name of possibleNames) {

    // Exact match first
    if (data[name] !== undefined && data[name] !== null && data[name] !== "") {
      return data[name];
    }

    // Flexible match
    const normalizedName = name
      .toLowerCase()
      .replace(/[^a-z0-9]/g, "");

    const matchingKey = keys.find(key => {
      const normalizedKey = key
        .toLowerCase()
        .replace(/[^a-z0-9]/g, "");

      return normalizedKey === normalizedName;
    });

    if (
      matchingKey &&
      data[matchingKey] !== undefined &&
      data[matchingKey] !== null &&
      data[matchingKey] !== ""
    ) {
      return data[matchingKey];
    }
  }

  return "";
}


// ============================================================
// 1. EXTRACT FORM / GOOGLE SHEETS DATA
// ============================================================

const sheetName = findField(item, [
  "Full Name",
  "Name",
  "FullName"
]);

const sheetEmail = findField(item, [
  "Email Address",
  "Email",
  "EmailAddress"
]);

const sheetPhone = findField(item, [
  "Phone Number",
  "Phone",
  "PhoneNumber",
  "Mobile",
  "Contact Number"
]);

const sheetRole = findField(item, [
  "Role Applied For",
  "Role",
  "Position",
  "Job Role",
  "RoleAppliedFor"
]);

const sheetResume = findField(item, [
  "Resume Link / Text",
  "Resume Link",
  "Resume Text",
  "Resume",
  "CV",
  "CV Link"
]);


// ============================================================
// 2. CHECK WHETHER THIS IS FORM/SHEET DATA
// ============================================================

const hasFormData = Boolean(
  sheetName ||
  sheetEmail ||
  sheetPhone ||
  sheetRole ||
  sheetResume
);


// ============================================================
// 3. GMAIL HEADER HELPER
// ============================================================

function getGmailHeader(headers, headerName) {

  if (!Array.isArray(headers)) {
    return "";
  }

  const header = headers.find(
    h =>
      String(h.name || "").toLowerCase() ===
      headerName.toLowerCase()
  );

  return header?.value || "";
}


// ============================================================
// 4. DECODE GMAIL BODY
// ============================================================

function decodeBase64Url(data) {

  if (!data) {
    return "";
  }

  try {

    const base64 = data
      .replace(/-/g, "+")
      .replace(/_/g, "/");

    return Buffer
      .from(base64, "base64")
      .toString("utf8");

  } catch (error) {

    return "";
  }
}


// ============================================================
// 5. EXTRACT GMAIL BODY RECURSIVELY
// ============================================================

function extractGmailBody(part) {

  if (!part) {
    return "";
  }

  // Direct body
  if (part.body?.data) {

    const decoded = decodeBase64Url(part.body.data);

    if (decoded) {
      return decoded;
    }
  }

  // Nested Gmail parts
  if (Array.isArray(part.parts)) {

    for (const child of part.parts) {

      const text = extractGmailBody(child);

      if (text) {
        return text;
      }
    }
  }

  return "";
}


// ============================================================
// 6. IF FORM / GOOGLE SHEETS DATA EXISTS
// ============================================================

if (hasFormData) {

  return {
    json: {

      name:
        String(sheetName || "Unknown Applicant").trim(),

      email:
        String(sheetEmail || "").trim(),

      phone:
        sheetPhone
          ? String(sheetPhone).trim()
          : null,

      source:
        "form",

      role_applied:
        String(
          sheetRole || "General Application"
        ).trim(),

      resume_text:
        String(sheetResume || "").trim(),

      applied_at:
        new Date().toISOString()

    }
  };
}


// ============================================================
// 7. OTHERWISE PROCESS GMAIL DATA
// ============================================================

let rawFrom =
  item.From ||
  item.from ||
  "";


// Look inside Gmail payload headers
if (item.payload?.headers) {

  const fromHeader = getGmailHeader(
    item.payload.headers,
    "From"
  );

  if (fromHeader) {
    rawFrom = fromHeader;
  }
}


// ============================================================
// 8. EXTRACT EMAIL ADDRESS
// ============================================================

const emailMatch =
  String(rawFrom).match(/<([^>]+)>/);

const gmailEmail =
  emailMatch
    ? emailMatch[1].trim()
    : String(rawFrom).trim();


// ============================================================
// 9. EXTRACT NAME
// ============================================================

const gmailName =
  String(rawFrom).includes("<")
    ? String(rawFrom)
        .split("<")[0]
        .replace(/"/g, "")
        .trim()
    : gmailEmail;


// ============================================================
// 10. EXTRACT SUBJECT
// ============================================================

let gmailSubject =
  item.Subject ||
  item.subject ||
  "";

if (!gmailSubject && item.payload?.headers) {

  gmailSubject = getGmailHeader(
    item.payload.headers,
    "Subject"
  );
}


// ============================================================
// 11. EXTRACT EMAIL BODY
// ============================================================

let gmailBody =
  item.textPlain ||
  item.text ||
  item.body ||
  "";


// Try Gmail payload
if (!gmailBody && item.payload) {

  gmailBody =
    extractGmailBody(item.payload);
}


// Last fallback
if (!gmailBody) {

  gmailBody =
    item.snippet ||
    "";
}


// ============================================================
// 12. RETURN NORMALIZED GMAIL DATA
// ============================================================

return {
  json: {

    name:
      gmailName ||
      "Email Applicant",

    email:
      gmailEmail ||
      "",

    phone:
      null,

    source:
      "email",

    role_applied:
      gmailSubject ||
      "General Application",

    resume_text:
      gmailBody ||
      "",

    applied_at:
      new Date().toISOString()

  }
};

// Safely extract text string from Gemini's nested response structure
let rawText = "";

if ($json.content && $json.content.parts && $json.content.parts[0] && $json.content.parts[0].text) {
  rawText = $json.content.parts[0].text;
} else if (typeof $json.text === 'string') {
  rawText = $json.text;
} else if (typeof $json === 'string') {
  rawText = $json;
} else {
  rawText = JSON.stringify($json);
}

// Clean up markdown code fences (```json ... ```)
const cleanedText = rawText.replace(/```json/gi, '').replace(/```/g, '').trim();

let parsedData = {};

try {
  parsedData = JSON.parse(cleanedText);
} catch (error) {
  // Fallback defaults in case AI response parsing fails
  parsedData = {
    ats_score: 50,
    classification: "Average",
    summary: "Could not parse AI evaluation output."
  };
}

// Retrieve candidate ID created in the Supabase 'Create a row' node
const candidateId = $('insert into database').item.json.id;

return {
  id: candidateId,
  ats_score: Number(parsedData.ats_score) || 0,
  classification: parsedData.classification || "Average",
  manager_notes: parsedData.summary || ""
};
